Let $X$ be a scheme.
\begin{enumerate}
\item If $D \subset X$ is an effective Cartier divisor, then
the canonical section $1_D$ of $\mathcal{O}_X(D)$ is regular.
\item Conversely, if $s$ is a regular section of the invertible
sheaf $\mathcal{L}$, then there exists a unique effective
Cartier divisor $D = Z(s) \subset X$ and a unique isomorphism
$\mathcal{O}_X(D) \to \mathcal{L}$ which maps $1_D$ to $s$.
\end{enumerate}
The constructions
$D \mapsto (\mathcal{O}_X(D), 1_D)$ and $(\mathcal{L}, s) \mapsto Z(s)$
give mutually inverse maps
$$
\left\{
\begin{matrix}
\text{effective Cartier divisors on }X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{isomorphism classes of pairs }(\mathcal{L}, s)\\
\text{consisting of an invertible }
\mathcal{O}_X\text{-module}\\
\mathcal{L}\text{ and a regular global section }s
\end{matrix}
\right\}
$$

For $(M, \theta) \in DD_{S/R}$, the diagram
\begin{equation}

\xymatrix@C=8pc{
C(M \otimes_{S, \delta_{12}^1} S_3)
\ar@<1ex>[r]^{C((\theta \otimes \delta_2^2) \circ (1_M \otimes \delta^2_0))}
\ar@<-1ex>[r]_{C(1_{M \otimes S_2} \otimes \delta^2_1)} &
C(M \otimes_{S, \delta_1^1} S_2 )
\ar[r]^{C(\theta \circ (1_M \otimes \delta_0^1))} & C(M).
}
\end{equation}
obtained by applying $C$ to (\ref{equation-equalizer-M}) is a split
coequalizer.

Let $(A, \mathfrak m)$ be a Noetherian $1$-dimensional local ring.
Let $f \in \mathfrak m$. The following are equivalent
\begin{enumerate}
\item $\mathfrak m = \sqrt{(f)}$,
\item $f$ is not contained in any minimal prime of $A$, and
\item $A_f = \prod_{\mathfrak p\text{ minimal}} A_\mathfrak p$ as $A$-algebras.
\end{enumerate}
Such an $f \in \mathfrak m$ exists. If $\text{depth}(A) = 1$ (for example
$A$ is reduced), then (1) -- (3) are also equivalent to
\begin{enumerate}
\item[(4)] $f$ is a nonzerodivisor,
\item[(5)] $A_f$ is the total ring of fractions of $A$.
\end{enumerate}
If $A$ is reduced, then (1) -- (5) are also equivalent to
\begin{enumerate}
\item[(6)] $A_f$ is the product of the residue fields at the minimal
primes of $A$.
\end{enumerate}

For $(M,\theta) \in DD_{S/R}$, the diagram
\begin{equation}

\xymatrix@C=8pc{
M \ar[r]^{\theta \circ (1_M \otimes \delta_0^1)} &
M \otimes_{S, \delta_1^1} S_2
\ar@<1ex>[r]^{(\theta \otimes \delta_2^2) \circ (1_M \otimes \delta^2_0)}
\ar@<-1ex>[r]_{1_{M \otimes S_2} \otimes \delta^2_1} & 
M \otimes_{S, \delta_{12}^1} S_3
}
\end{equation}
is a split equalizer.

For any ring $A$ there exists an extension $A \subset B$ such that
\begin{enumerate}
\item $B$ is a filtered colimit of finite free $A$-algebras,
\item $B$ is free as an $A$-module, and
\item $B$ is absolutely integrally closed.
\end{enumerate}

The diagram
\begin{equation}

\xymatrix@C=8pc{
S_1 \ar[r]^{\delta^1_1} &
S_2 \ar@<1ex>[r]^{\delta^2_2} \ar@<-1ex>[r]_{\delta^2_1} & 
S_3
}
\end{equation}
is a split equalizer.
